INSERT INTO LIVROS_NOMES (NOME, ESTADO, MOTIVO, CRIADO_EM) SELECT X.TITULO, 'NAO_LIVRO', 'Decidido pela pessoa', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS X WHERE X.ID = {{id}} ON DUPLICATE KEY UPDATE ESTADO = 'NAO_LIVRO', CATALOGO_ID = NULL, MOTIVO = VALUES(MOTIVO)